import{_ as t,a,b as o}from"./chunks/image3.BqVg1dc4.js";import{_ as i,o as r,c as s,ag as n}from"./chunks/framework.D9ghT4bC.js";const _=JSON.parse('{"title":"Civilization Score Calculation","description":"","frontmatter":{},"headers":[],"relativePath":"Community/Code-analysis/Score-calculation/index.md","filePath":"Community/Code-analysis/Score-calculation/index.md"}'),l={name:"Community/Code-analysis/Score-calculation/index.md"};function c(d,e,p,h,m,u){return r(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="civilization-score-calculation" tabindex="-1">Civilization Score Calculation <a class="header-anchor" href="#civilization-score-calculation" aria-label="Permalink to &quot;Civilization Score Calculation&quot;">​</a></h1><blockquote><p>Author: 华花 Version: 4.19.12 Date: 2026-02-14</p></blockquote><h2 id="foreword" tabindex="-1">Foreword <a class="header-anchor" href="#foreword" aria-label="Permalink to &quot;Foreword&quot;">​</a></h2><p>As the first element of the statistics report, the civ score is often taken seriously by newcomers, while experienced players agree it&#39;s actually meaningless.</p><h2 id="_1-score-ratio-by-map-size" tabindex="-1">1. Score ratio by map size <a class="header-anchor" href="#_1-score-ratio-by-map-size" aria-label="Permalink to &quot;1. Score ratio by map size&quot;">​</a></h2><p>Standard medium map: 1276 tiles (Civ V standard map: 80×52=4160). t = 1276 / total tiles of the map used; if t &gt; 1, t = 1 + (t-1)/3.</p><h2 id="_2-score-components" tabindex="-1">2. Score components <a class="header-anchor" href="#_2-score-components" aria-label="Permalink to &quot;2. Score components&quot;">​</a></h2><ul><li><strong>Cities score</strong> = number of cities × 10 × t</li><li><strong>Population score</strong> = total population × 3 × t</li><li><strong>Tiles score</strong> = non-water tiles owned (water = shallow sea/ocean, lakes don&#39;t count) × 1 × t</li><li><strong>Wonders score</strong> = world wonders owned × 20</li><li><strong>Techs score</strong> = techs researched × 4</li><li><strong>Future techs score</strong> = future techs researched × 10</li></ul><h2 id="_3-summing-up" tabindex="-1">3. Summing up <a class="header-anchor" href="#_3-summing-up" aria-label="Permalink to &quot;3. Summing up&quot;">​</a></h2><p>Add all components to get the final civilization score.</p><h2 id="_4-worked-example" tabindex="-1">4. Worked example <a class="header-anchor" href="#_4-worked-example" aria-label="Permalink to &quot;4. Worked example&quot;">​</a></h2><p>Let&#39;s verify the formula with a real game:</p><p><img src="'+t+'" alt=""><img src="'+a+'" alt=""></p><p>This is a large map (66×43=2838, t=0.4496); we&#39;re the Dutch with 9 cities and 65 population; 2 water tiles, territory 102; 3 wonders built; 20 techs researched. The score is:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0.4496 × (90 + 195 + 102) + 120 + 80 = 373.99</span></span></code></pre></div><p>Which matches the shown 374 points.</p><h2 id="_5-tips" tabindex="-1">5. Tips <a class="header-anchor" href="#_5-tips" aria-label="Permalink to &quot;5. Tips&quot;">​</a></h2><ul><li>Smaller maps yield higher scores for equal development; larger maps the opposite.</li><li>Since future techs are rarely researched multiple times in normal games, the civ score can be approximated from report data plus the wonder count in the politics panel — meaning the civ score has no tactical significance.</li><li>In normal games the civ score slowly rises with cities, population, natural expansion and techs; sudden jumps usually come from founding/capturing/marrying cities, completing several wonders, or bulbing many techs at the endgame.</li><li>The civ score reflects long-term strength to some degree; unlike other report data (production, gold, etc.) it rarely swings wildly in the short term. But in-game, pay more attention to short-term data (military rating, key culture milestones) to read the situation and make decisions.</li></ul><h2 id="_6-code-reference" tabindex="-1">6. Code reference <a class="header-anchor" href="#_6-code-reference" aria-label="Permalink to &quot;6. Code reference&quot;">​</a></h2><p><code>core\\src\\com\\unciv\\logic\\civilization\\Civlization</code></p><p>(Note: in the current version the score ratios are defined by the ruleset — read the G&amp;K code for the concrete values)</p><p><img src="'+o+'" alt=""></p>',22)])])}const b=i(l,[["render",c]]);export{_ as __pageData,b as default};
